            let e = 0
            let w = 0
            let n = 0
            for k in 0..len(lines) {
                let lv = level_of(lines[k])
                if str_eq(lv, "ERROR") { e = e + 1 }
                if str_eq(lv, "WARN") { w = w + 1 }
                if str_eq(lv, "INFO") { n = n + 1 }
            }
            let body = "ERROR={to_str(e)}\nWARN={to_str(w)}\nINFO={to_str(n)}\n"
            match write_file("./out/levels.txt", body) {
                Ok(_) => {
